import {positionMath} from './math.js';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
const palette=['#200b3c','#56238c','#9945ff','#24bcb0','#14f195','#f1fff9'];
const noise=(x,y)=>{const n=Math.sin(x*127.1+y*311.7)*43758.5453;return n-Math.floor(n);};
const money=x=>Number(x).toLocaleString('en-US',{maximumFractionDigits:2,minimumFractionDigits:2});
export function fitCanvas(canvas){const rect=canvas.getBoundingClientRect();const dpr=Math.min(devicePixelRatio||1,2);const w=Math.max(1,Math.round(rect.width)),h=Math.max(1,Math.round(rect.height));if(canvas.width!==Math.round(w*dpr)||canvas.height!==Math.round(h*dpr)){canvas.width=w*dpr;canvas.height=h*dpr;}const ctx=canvas.getContext('2d');ctx.setTransform(dpr,0,0,dpr,0,0);return {ctx,w,h};}
export function drawPriceChart(canvas,candles=[],options={}){
 if(!canvas)return;const {ctx:c,w,h}=fitCanvas(canvas);c.clearRect(0,0,w,h);const pad={l:10,r:65,t:22,b:25};const pw=w-pad.l-pad.r,ph=h-pad.t-pad.b;
 if(!candles.length){c.fillStyle='#7c89a4';c.font='12px Geist';c.textAlign='center';c.fillText('Market history temporarily unavailable',w/2,h/2);return;}
 const values=candles.map(a=>a.close);const include=[...values];if(options.liquidation)include.push(options.liquidation);if(options.entry)include.push(options.entry);let lo=Math.min(...include),hi=Math.max(...include);const range=Math.max(hi-lo,hi*.025);lo-=range*.15;hi+=range*.15;
 const x=i=>pad.l+i/(Math.max(values.length-1,1))*pw,y=v=>pad.t+(hi-v)/(hi-lo)*ph;
 c.font='9px Geist Mono';c.lineWidth=1;for(let i=0;i<5;i++){const yy=pad.t+ph*i/4;c.strokeStyle='#131c2d';c.setLineDash([2,7]);c.beginPath();c.moveTo(pad.l,yy);c.lineTo(w-pad.r,yy);c.stroke();c.fillStyle='#667795';c.textAlign='left';c.fillText(money(hi-(hi-lo)*i/4),w-pad.r+8,yy+3);}c.setLineDash([]);
 const gradient=c.createLinearGradient(0,0,0,h);gradient.addColorStop(0,'#9945ff35');gradient.addColorStop(1,'#9945ff00');c.beginPath();values.forEach((v,i)=>i?c.lineTo(x(i),y(v)):c.moveTo(x(i),y(v)));c.lineTo(x(values.length-1),pad.t+ph);c.lineTo(x(0),pad.t+ph);c.closePath();c.fillStyle=gradient;c.fill();
 c.beginPath();values.forEach((v,i)=>i?c.lineTo(x(i),y(v)):c.moveTo(x(i),y(v)));c.strokeStyle=options.color||'#80f4c6';c.lineWidth=1.7;c.stroke();
 if(options.entry){c.setLineDash([3,5]);c.strokeStyle='#8b96ac';c.beginPath();c.moveTo(pad.l,y(options.entry));c.lineTo(w-pad.r,y(options.entry));c.stroke();c.fillStyle='#a0acc2';c.textAlign='left';c.fillText('ENTRY',15,y(options.entry)-6);}
 if(options.liquidation){const yy=y(options.liquidation);c.fillStyle='#ff7a7a0d';if(options.side==='short')c.fillRect(pad.l,pad.t,pw,yy-pad.t);else c.fillRect(pad.l,yy,pw,pad.t+ph-yy);c.setLineDash([5,4]);c.strokeStyle='#ff7a7a';c.beginPath();c.moveTo(pad.l,yy);c.lineTo(w-pad.r,yy);c.stroke();c.fillStyle='#ff7a7a';c.textAlign='right';c.fillText('LIQ '+money(options.liquidation),w-pad.r-5,yy-7);}
 c.setLineDash([]);const cursor=options.cursor??values.length-1;const index=Math.min(values.length-1,Math.max(0,Math.floor(cursor)));c.fillStyle='#fff';c.shadowColor='#9945ff';c.shadowBlur=9;c.fillRect(x(index)-2.5,y(values[index])-2.5,5,5);c.shadowBlur=0;c.fillStyle='#667795';c.textAlign='left';c.fillText(new Date(candles[0].time).toLocaleDateString('en-US',{month:'short',day:'numeric'}),pad.l,h-5);c.textAlign='right';c.fillText(new Date(candles.at(-1).time).toLocaleDateString('en-US',{month:'short',day:'numeric'}),w-pad.r,h-5);
}
export function startMotion(getData){
 const canvases=$$('canvas.field-canvas,#hero-ribbon');const visible=new WeakMap();const observer=new IntersectionObserver(entries=>entries.forEach(e=>visible.set(e.target,e.isIntersecting)),{rootMargin:'50px'});canvases.forEach(c=>observer.observe(c));
 let activeLens=0,forcedUntil=0,last=0,launchProgress=0,launchRunning=!reduced,replayRunning=!reduced,replayProgress=0,preset=0;const start=performance.now();
 $$('.lens-labels button').forEach(b=>b.addEventListener('click',()=>{activeLens=Number(b.dataset.lens);forcedUntil=performance.now()+7000;updateLensLabels();}));
 function updateLensLabels(){$$('.lens-labels button').forEach((b,i)=>b.classList.toggle('active',i===activeLens));$('#lens').setAttribute('aria-label','Solvia pixel identity: '+['Swap','Liquidity','Launch','Perps','Launchpad'][activeLens]);}
 function dither(c,w,h,cell,brightness){c.clearRect(0,0,w,h);for(let y=0,j=0;y<h;y+=cell,j++)for(let x=0,i=0;x<w;x+=cell,i++){const value=brightness(x/w,y/h,i,j);if(value<.035)continue;const threshold=noise(i,j);if(threshold>Math.min(1,value*1.7))continue;const color=Math.min(5,Math.max(0,Math.floor(value*5+threshold*.8)));c.fillStyle=palette[color];const size=cell*(.45+.26*Math.min(value,1));c.fillRect(x,y,size,size);}}
 function lens(canvas,t){const {ctx:c,w,h}=fitCanvas(canvas);const s=Math.min(w,h),cx=w/2,cy=h/2;dither(c,w,h,4.2,(x,y,i,j)=>{const xx=(x-.5)*2,yy=(y-.5)*2,r=Math.hypot(xx,yy),angle=Math.atan2(yy,xx);if(r>1)return 0;let v=0;if(r>.87&&r<.995){const band=Math.sin((r-.87)/.125*Math.PI);v=band*(.12+.25*Math.pow(Math.max(0,Math.cos(angle*3-t*.35)),2));if(Math.abs(r-.955)<.012)v+=.2*Math.max(0,Math.cos(angle-t*.4));}if(r<.83&&noise(i+Math.floor(t),j)>.989)v=.13;const u=(xx/.76+1)/2,z=(yy/.76+1)/2;let shape=0;if(activeLens===0){const bar1=z>.3&&z<.4&&u>.18&&u<.72,bar2=z>.6&&z<.7&&u>.28&&u<.82;const head1=u>.62&&u<.84&&Math.abs(z-.35)<(u-.62)*.9,head2=u>.16&&u<.38&&Math.abs(z-.65)<(.38-u)*.9;if(bar1||head1)shape=.95;if(bar2||head2)shape=.55;}
 if(activeLens===1){const col=Math.floor(u*17),local=u*17-col;const height=.12+.65*Math.exp(-Math.pow((col-8)/4.2,2));if(u>.08&&u<.92&&local<.65&&z>.86-height&&z<.86)shape=col===8?1:.35+.35*(1-z);}
 if(activeLens===2&&u>.1&&u<.88&&z<.88){const curve=.86-Math.pow((u-.1)/.78,2)*.67;if(Math.abs(z-curve)<.018)shape=1;else if(z>curve)shape=.2;}
 if(activeLens===3&&u>.1&&u<.9){const curve=.28+.12*Math.sin(u*12)+Math.pow(u,2)*.55;if(Math.abs(z-curve)<.018)shape=.9;if(Math.abs(z-.78)<.009&&i%3)shape=.55;}
 if(activeLens===4&&u>.1&&u<.9&&z>.15&&z<.85){if(Math.abs(u-.1)<.02||Math.abs(u-.9)<.02||Math.abs(z-.15)<.02||Math.abs(z-.85)<.02)shape=.8;if(z<.29&&z>.24)shape=.35;if(u>.2&&u<.34&&z>.4&&z<.55)shape=.9;if(u>.42&&u<.8&&Math.abs(z-.46)<.025)shape=.5;if(u>.2&&u<.78&&Math.abs(z-.68)<.025)shape=.45;}
 return Math.max(v,shape*(.88+.12*Math.sin(t*1.3+x*3)));});}
 function ribbon(canvas,t,footer=false){const {ctx:c,w,h}=fitCanvas(canvas);dither(c,w,h,6.4,(x,y,i,j)=>{const distance=x-.5;const middle=footer?.91+.035*Math.sin(x*8+t*.35):1.28-2*distance*distance;const width=footer?.22:.09+Math.abs(distance)*.14;const off=(y-middle)/width;if(Math.abs(off)>1.6)return 0;const body=Math.max(0,1-Math.abs(off)*.6);const stripe=Math.exp(-Math.pow((off+.16+.18*Math.sin(x*6+t*.2))/.17,2));const fold=.5+.5*Math.sin(x*24-off*3+t*.7);return Math.min(1,body*(.08+fold*.22)+stripe*(.52+.48*fold));});}
 function horizon(canvas,t){const {ctx:c,w,h}=fitCanvas(canvas);dither(c,w,h,5.6,(x,y,i,j)=>{const yy=y-.45;const curve=.58+.05*Math.sin(x*7+t*.4);const intensity=Math.exp(-Math.pow((y-curve)/.24,2));return intensity*(.04+.28*Math.pow(Math.max(0,Math.cos(x*15+yy*8-t*.5)),3));});}
 let lastLaunch=-1,lastReplay=0;function frame(now){requestAnimationFrame(frame);if(document.hidden||document.body.classList.contains('in-app')||document.body.classList.contains('in-docs'))return;if(now-last<(reduced?1000:60))return;const dt=last?Math.min(now-last,200):0;last=now;const t=reduced?0:(now-start)/1000;if(now>forcedUntil&&!reduced){const current=Math.floor(Math.max(0,t)/3.5)%5;if(current!==activeLens){activeLens=current;updateLensLabels();}}
 for(const canvas of canvases){if(!visible.get(canvas))continue;if(canvas.id==='lens')lens(canvas,t);else if(canvas.id==='hero-ribbon')ribbon(canvas,t);else if(canvas.dataset.field==='footer')ribbon(canvas,t,true);else horizon(canvas,t);}
 }updateLensLabels();requestAnimationFrame(frame);return {refresh(){}};
}
